CHUNIN_PARTS = {'chunin_yelek', 'chunin_yelek_acik', 'suna_yelek', 'kiri_yelek', 'kumo_yelek', 'iwa_yelek', 'jonin_koyu'}
JONIN_PARTS = {'konoha_jonin', 'suna_jonin', 'kiri_jonin', 'kumo_jonin', 'iwa_jonin', 'jonin_komutan_paltosu'}
VIL_PARTS = {'konoha': {'chunin_yelek', 'chunin_yelek_acik', 'konoha_jonin'}, 'suna': {'suna_yelek', 'suna_jonin'}, 'kiri': {'kiri_yelek', 'kiri_jonin', 'kiri_koruma'},
             'kumo': {'kumo_yelek', 'kumo_jonin', 'kumo_kaval'}, 'iwa': {'iwa_yelek', 'iwa_jonin', 'iwa_pant'}}

FLAV = {'s': {'speed': 0.04}, 'm': {'melee': 0.05}, 'c': {'chakra': 20}, 'h': {'hp': 20}, 'd': {'def': 4}}
BASE = [{'def': 5, 'hp': 10}, {'def': 8, 'hp': 15}, {'def': 12, 'hp': 25}, {'def': 15, 'hp': 30, 'chakra': 15}]
PRICE = [250, 500, 900, 1500]

def col(h):
    if h is None:
        return 'null'
    r, g, b = int(h[0:2], 16) / 255, int(h[2:4], 16) / 255, int(h[4:6], 16) / 255
    return 'Color(%.3f, %.3f, %.3f)' % (r, g, b)

def gd_val(v):
    if isinstance(v, float): return repr(round(v, 3))
    return str(v)

out = ['extends RefCounted', '## OTOMATİK ÜRETİLDİ: tools/gen_striker_sets.py (refs/outfits_ss Shinobi Striker kostüm referansları).',
       '## Mevcut kıyafet parçalarından setler; "sex": "f"/"m" yalnız o cinsiyete satılır/seçilir, boş = herkes.', '', 'const SETS := {']
start, shop = [], []
seen = set()
for (i, sid, name, desc, fl, parts) in D:
    sex, rk, page = lst[i] if i >= 0 else ('U', 'A', '')
    sex = SEX_FIX.get(i, sex)   # wiki sayfa metni kategoriden farklıysa (Rock Striker: yalnız erkek)
    r = rank_of(rk)
    sid = 'ss_' + re.sub(r'[^a-z0-9_]', '', sid.replace('ş', 's'))
    sex = SEX_SID.get(sid, sex)   # varyasyona özel cinsiyet (wiki: Beach Flamingo yalnız kadın vb.)
    assert sid not in seen, sid
    seen.add(sid)
    # rütbe ve köy giysinin kendisinden: taktik yelek = chūnin, jōnin haorisi = jōnin, ANBU parçası = ANBU, Kage cübbesi = Kage
    pn = [p for (p, a, b) in parts]
    need = 0
    vil = ''
    for p in pn:
        for v, ks in VIL_PARTS.items():
            if p in ks:
                vil = v
        if p in CHUNIN_PARTS: need = max(need, 2)
        if p in JONIN_PARTS: need = max(need, 3)
        if p.startswith('anbu_'): need = max(need, 4)
        if p == 'kage_cubbesi': need = max(need, 6)
        if p == 'hokage_haori':   # Hokage haorisi (Minato): yalnız Konoha Kage'si
            need = max(need, 6); vil = 'konoha'
    st = dict(BASE[r])
    for k, v in FLAV[fl].items():
        st[k] = st.get(k, 0) + v
    stats = '{' + ', '.join('"%s": %s' % (k, gd_val(v)) for k, v in st.items()) + '}'
    ps = ', '.join('["%s", %s, %s]' % (p, col(a), col(b)) for (p, a, b) in parts)
    sx = {'F': 'f', 'M': 'm'}.get(sex, '')
    vk = (', "village": "%s"' % vil) if vil else ''
    out.append('\t"%s": {"name": "%s", "slot": "set", "price": %d, "rank": %d%s, "sex": "%s", "desc": "%s", "stats": %s, "c1": %s, "c2": %s, "parts": [%s]},'
               % (sid, name, PRICE[r], need, vk, sx, desc, stats, col(parts[0][1]), col(parts[0][2] or parts[0][1]), ps))
    if sid in DONE:   # yalnız gerçekten modellenmiş (ref'e göre yeni 3B parçalı) setler satılır/seçilir
        shop.append(sid)
        if r == 0 and need == 0:
            start.append(sid)
out.append('}')
out.append('')
out.append('## Başlangıçta seçilebilen temel (C sırası) setler')
out.append('const START := [%s]' % ', '.join('"%s"' % s for s in start))
out.append('const SHOP := [%s]' % ', '.join('"%s"' % s for s in shop))
open(os.path.join(ROOT, 'godot/scripts/core/striker_sets.gd'), 'w', encoding='utf-8', newline='\n').write('\n'.join(out) + '\n')
print(len(shop), 'set', len(start), 'başlangıç')
